# ---------------------------------------------------------------------------
# Port of SAM reciter + parser (from the JS port of Sebastian Macke's C SAM).
# ---------------------------------------------------------------------------

FLAG_NUMERIC = 0x01
FLAG_RULESET2 = 0x02
FLAG_VOICED = 0x04
FLAG_0X08 = 0x08
FLAG_DIPHTHONG = 0x10
FLAG_CONSONANT = 0x20
FLAG_VOWEL_OR_Y = 0x40
FLAG_ALPHA_OR_QUOT = 0x80

pR, pD, pT = 23, 57, 69
FLAG_FRICATIVE = 0x2000
FLAG_LIQUIC = 0x1000
FLAG_NASAL = 0x0800
FLAG_ALVEOLAR = 0x0400
FLAG_PUNCT = 0x0100
FLAG_VOWEL = 0x0080
P_FLAG_CONSONANT = 0x0040
FLAG_DIP_YX = 0x0020
P_FLAG_DIPHTHONG = 0x0010
FLAG_0008 = 0x0008
P_FLAG_VOICED = 0x0004
FLAG_STOPCONS = 0x0002
FLAG_UNVOICED_STOPCONS = 0x0001


def _js_substr(s, start, length):
    if start < 0:
        start = max(len(s) + start, 0)
    return s[start:start + length]


def _ch(text, pos):
    """text[pos] with JS semantics (undefined -> None)."""
    if 0 <= pos < len(text):
        return text[pos]
    return None


def _flags(c, flg):
    cf = CHAR_FLAGS.get(c) if c is not None else None
    return ((cf or 0) & flg) != 0


def _flags_at(text, pos, flg):
    return _flags(_ch(text, pos), flg)


_TCS = ('T', 'C', 'S')
_EIY = ('E', 'I', 'Y')


class _Rule:
    def __init__(self, rule_string):
        splitted = rule_string.split('=')
        self.target = splitted.pop()
        source = '='.join(splitted).split('(')
        tmp = source.pop().split(')')
        self.pre = source[0]
        self.match = tmp[0]
        self.post = tmp[1]
        self.c = self.match[0]

    def check_prefix(self, text, pos):
        pre = self.pre
        for rule_pos in range(len(pre) - 1, -1, -1):
            rb = pre[rule_pos]
            if not _flags(rb, FLAG_ALPHA_OR_QUOT):
                if rb == ' ':
                    pos -= 1
                    ok = not _flags_at(text, pos, FLAG_ALPHA_OR_QUOT)
                elif rb == '#':
                    pos -= 1
                    ok = _flags_at(text, pos, FLAG_VOWEL_OR_Y)
                elif rb == '.':
                    pos -= 1
                    ok = _flags_at(text, pos, FLAG_0X08)
                elif rb == '&':
                    pos -= 1
                    ok = _flags_at(text, pos, FLAG_DIPHTHONG)
                    if not ok:
                        pos -= 1
                        ok = _js_substr(text, pos, 2) in ('CH', 'SH')
                elif rb == '@':
                    pos -= 1
                    if _flags_at(text, pos, FLAG_VOICED):
                        ok = True
                    else:
                        ic = _ch(text, pos)
                        # 'H' is never in TCS: always false (as in JS)
                        ok = False if ic != 'H' else (ic in _TCS)
                elif rb == '^':
                    pos -= 1
                    ok = _flags_at(text, pos, FLAG_CONSONANT)
                elif rb == '+':
                    pos -= 1
                    ok = _ch(text, pos) in _EIY
                elif rb == ':':
                    while pos >= 0:
                        if not _flags_at(text, pos - 1, FLAG_CONSONANT):
                            break
                        pos -= 1
                    ok = True
                else:
                    raise TypeError('bad prefix rule char ' + rb)
                if not ok:
                    return False
            else:
                pos -= 1
                if _ch(text, pos) != rb:
                    return False
        return True

    def check_suffix(self, text, pos):
        post = self.post
        for rule_pos in range(len(post)):
            rb = post[rule_pos]
            if not _flags(rb, FLAG_ALPHA_OR_QUOT):
                if rb == ' ':
                    pos += 1
                    ok = not _flags_at(text, pos, FLAG_ALPHA_OR_QUOT)
                elif rb == '#':
                    pos += 1
                    ok = _flags_at(text, pos, FLAG_VOWEL_OR_Y)
                elif rb == '.':
                    pos += 1
                    ok = _flags_at(text, pos, FLAG_0X08)
                elif rb == '&':
                    pos += 1
                    ok = _flags_at(text, pos, FLAG_DIPHTHONG)
                    if not ok:
                        pos += 1
                        ok = _js_substr(text, pos - 2, 2) in ('HC', 'HS')
                elif rb == '@':
                    pos += 1
                    if _flags_at(text, pos, FLAG_VOICED):
                        ok = True
                    else:
                        ic = _ch(text, pos)
                        ok = False if ic != 'H' else (ic in _TCS)
                elif rb == '^':
                    pos += 1
                    ok = _flags_at(text, pos, FLAG_CONSONANT)
                elif rb == '+':
                    pos += 1
                    ok = _ch(text, pos) in _EIY
                elif rb == ':':
                    while _flags_at(text, pos + 1, FLAG_CONSONANT):
                        pos += 1
                    ok = True
                elif rb == '%':
                    if _ch(text, pos + 1) != 'E':
                        if _js_substr(text, pos + 1, 3) == 'ING':
                            pos += 3
                            ok = True
                        else:
                            ok = False
                    elif not _flags_at(text, pos + 2, FLAG_ALPHA_OR_QUOT):
                        pos += 1
                        ok = True
                    elif _ch(text, pos + 2) not in ('R', 'S', 'D'):
                        if _ch(text, pos + 2) != 'L':
                            if _js_substr(text, pos + 2, 3) == 'FUL':
                                pos += 4
                                ok = True
                            else:
                                ok = False
                        elif _ch(text, pos + 3) != 'Y':
                            ok = False
                        else:
                            pos += 3
                            ok = True
                    else:
                        pos += 2
                        ok = True
                else:
                    raise TypeError('bad suffix rule char ' + rb)
                if not ok:
                    return False
            else:
                pos += 1
                if _ch(text, pos) != rb:
                    return False
        return True

    def matches(self, text, pos):
        if not text.startswith(self.match, pos):
            return False
        if not self.check_prefix(text, pos):
            return False
        return self.check_suffix(text, pos + (len(self.match) - 1))


_RULES = {}
for _r in RULES.split('|'):
    _rule = _Rule(_r)
    _RULES.setdefault(_rule.c, []).append(_rule)
_RULES2 = [_Rule(_r) for _r in RULES2.split('|')]


def phonemes(text):
    """Reciter: English text -> phoneme string (False on a BRK char, as in JS)."""
    text = ' ' + text.upper()
    input_pos = 0
    output = ''
    c = 0
    while input_pos < len(text) and c < 10000:
        c += 1
        cur = text[input_pos]
        if cur != '.' or _flags_at(text, input_pos + 1, FLAG_NUMERIC):
            if _flags(cur, FLAG_RULESET2):
                for rule in _RULES2:
                    if rule.matches(text, input_pos):
                        input_pos += len(rule.match)
                        output += rule.target
                        break
                continue
            if CHAR_FLAGS.get(cur) != 0:
                if not _flags(cur, FLAG_ALPHA_OR_QUOT):
                    return False
                for rule in _RULES[cur]:
                    if rule.matches(text, input_pos):
                        input_pos += len(rule.match)
                        output += rule.target
                        break
                continue
            output += ' '
            input_pos += 1
            continue
        output += '.'
        input_pos += 1
    return output


# ----------------------------------------------------------------- parser

_UNDEF = object()  # JS `undefined` returned by getPhoneme out of range


def _has_flag(phoneme, flag):
    if isinstance(phoneme, int) and 0 <= phoneme < len(PHONEME_FLAGS):
        return (PHONEME_FLAGS[phoneme] & flag) != 0
    return False


def _comb(i):
    return COMBINED_LEN[i] if 0 <= i < len(COMBINED_LEN) else 0


def _parser1(inp, add_phoneme, add_stress):
    src = 0
    n = len(inp)
    while src < n:
        sign1 = inp[src]
        sign2 = inp[src + 1] if src + 1 < n else ''
        match = None
        two = sign1 + sign2
        for i, v in enumerate(PHONEME_NAME_TABLE):
            if v == two and v[1] != '*':
                match = i
                break
        if match is not None:
            src += 1
            add_phoneme(match)
            src += 1
            continue
        one = sign1 + '*'
        for i, v in enumerate(PHONEME_NAME_TABLE):
            if v == one:
                match = i
                break
        if match is not None:
            add_phoneme(match)
            src += 1
            continue
        m = len(STRESS_TABLE)
        while (STRESS_TABLE[m] if m < len(STRESS_TABLE) else None) != sign1 and m > 0:
            m -= 1
        if m == 0:
            raise ValueError('Could not parse char ' + sign1)
        add_stress(m)
        src += 1


def parse(text):
    """Reciter + parser: returns [(phonemeindex, length, stress) ...]."""
    inp = phonemes(text)
    if not inp:
        return False
    stress = []
    plen = []
    pidx = []

    def get_phoneme(pos):
        if pos == len(pidx):
            return None
        if 0 <= pos < len(pidx):
            return pidx[pos]
        return _UNDEF

    def set_phoneme(pos, v):
        pidx[pos] = v

    def get_stress(pos):
        return stress[pos] if 0 <= pos < len(stress) else 0

    def set_stress(pos, v):
        stress[pos] = v

    def get_length(pos):
        return plen[pos] if 0 <= pos < len(plen) else 0

    def set_length(pos, v):
        plen[pos] = v

    def put(lst, idx, v):
        if idx == len(lst):
            lst.append(v)
        else:
            lst[idx] = v

    def insert_phoneme(pos, value, stress_value, length=0):
        for i in range(len(pidx) - 1, pos - 1, -1):
            put(pidx, i + 1, pidx[i])
            put(plen, i + 1, get_length(i))
            put(stress, i + 1, get_stress(i))
        put(pidx, pos, value)
        put(plen, pos, length)
        put(stress, pos, stress_value)

    def add_phoneme(v):
        stress.append(0)
        plen.append(0)
        pidx.append(v)

    def add_stress(v):
        stress[len(pidx) - 1] = v

    _parser1(inp, add_phoneme, add_stress)
    _parser2(insert_phoneme, set_phoneme, get_phoneme, get_stress)
    _copy_stress(get_phoneme, get_stress, set_stress)
    _set_phoneme_length(get_phoneme, get_stress, set_length)
    _adjust_lengths(get_phoneme, set_length, get_length)
    _prolong(get_phoneme, insert_phoneme, get_stress)

    return [(v, plen[i], stress[i]) for i, v in enumerate(pidx) if v]


def _parser2(insert_phoneme, set_phoneme, get_phoneme, get_stress):
    def handle_uw_ch_j(phoneme, pos):
        if phoneme == 53:
            if _has_flag(get_phoneme(pos - 1), FLAG_ALVEOLAR):
                set_phoneme(pos, 16)
        elif phoneme == 42:
            insert_phoneme(pos + 1, 43, get_stress(pos))
        elif phoneme == 44:
            insert_phoneme(pos + 1, 45, get_stress(pos))

    def change_ax(position, suffix):
        set_phoneme(position, 13)
        insert_phoneme(position + 1, suffix, get_stress(position))

    pos = -1
    while True:
        pos += 1
        phoneme = get_phoneme(pos)
        if phoneme is None:
            break
        if phoneme == 0:
            continue
        if _has_flag(phoneme, P_FLAG_DIPHTHONG):
            insert_phoneme(pos + 1, 21 if _has_flag(phoneme, FLAG_DIP_YX) else 20, get_stress(pos))
            handle_uw_ch_j(phoneme, pos)
            continue
        if phoneme == 78:
            change_ax(pos, 24)
            continue
        if phoneme == 79:
            change_ax(pos, 27)
            continue
        if phoneme == 80:
            change_ax(pos, 28)
            continue
        if _has_flag(phoneme, FLAG_VOWEL) and get_stress(pos):
            if get_phoneme(pos + 1) == 0:
                phoneme = get_phoneme(pos + 2)
                if phoneme is not None and _has_flag(phoneme, FLAG_VOWEL) and get_stress(pos + 2):
                    insert_phoneme(pos + 2, 31, 0)
            continue

        prior = None if pos == 0 else get_phoneme(pos - 1)

        if phoneme == pR:
            if prior == pT:
                set_phoneme(pos - 1, 42)
            elif prior == pD:
                set_phoneme(pos - 1, 44)
            elif _has_flag(prior, FLAG_VOWEL):
                set_phoneme(pos, 18)
            continue

        if phoneme == 24 and _has_flag(prior, FLAG_VOWEL):
            set_phoneme(pos, 19)
            continue
        if prior == 60 and phoneme == 32:
            set_phoneme(pos, 38)
            continue

        if phoneme == 60:
            ph = get_phoneme(pos + 1)
            if not _has_flag(ph, FLAG_DIP_YX) and ph is not None:
                set_phoneme(pos, 63)
            continue

        if phoneme == 72:
            y = get_phoneme(pos + 1)
            if not _has_flag(y, FLAG_DIP_YX) or y is None:
                set_phoneme(pos, 75)
                phoneme = 75

        if _has_flag(phoneme, FLAG_UNVOICED_STOPCONS) and prior == 32:
            set_phoneme(pos, phoneme - 12)
        elif not _has_flag(phoneme, FLAG_UNVOICED_STOPCONS):
            handle_uw_ch_j(phoneme, pos)

        if phoneme == 69 or phoneme == 57:
            if pos > 0 and _has_flag(get_phoneme(pos - 1), FLAG_VOWEL):
                phoneme = get_phoneme(pos + 1)
                if phoneme == 0:
                    phoneme = get_phoneme(pos + 2)
                if _has_flag(phoneme, FLAG_VOWEL) and not get_stress(pos + 1):
                    set_phoneme(pos, 30)
            continue


def _copy_stress(get_phoneme, get_stress, set_stress):
    position = 0
    while True:
        phoneme = get_phoneme(position)
        if phoneme is None:
            break
        if _has_flag(phoneme, P_FLAG_CONSONANT):
            phoneme = get_phoneme(position + 1)
            if phoneme is not None and _has_flag(phoneme, FLAG_VOWEL):
                st = get_stress(position + 1)
                if st != 0 and st < 0x80:
                    set_stress(position, st + 1)
        position += 1


def _set_phoneme_length(get_phoneme, get_stress, set_length):
    position = 0
    while True:
        phoneme = get_phoneme(position)
        if phoneme is None:
            break
        st = get_stress(position)
        if st == 0 or st > 0x7F:
            set_length(position, _comb(phoneme) & 0xFF)
        else:
            set_length(position, _comb(phoneme) >> 8)
        position += 1


def _adjust_lengths(get_phoneme, set_length, get_length):
    position = 0
    while get_phoneme(position) is not None:
        if not _has_flag(get_phoneme(position), FLAG_PUNCT):
            position += 1
            continue
        loop_index = position
        while True:
            position -= 1
            if not (position > 1 and not _has_flag(get_phoneme(position), FLAG_VOWEL)):
                break
        if position == 0:
            break
        while position < loop_index:
            gp = get_phoneme(position)
            if not _has_flag(gp, FLAG_FRICATIVE) or _has_flag(gp, P_FLAG_VOICED):
                a = get_length(position)
                set_length(position, (a >> 1) + a + 1)
            position += 1
        position += 1

    loop_index = -1
    while True:
        loop_index += 1
        phoneme = get_phoneme(loop_index)
        if phoneme is None:
            break
        position = loop_index
        if _has_flag(phoneme, FLAG_VOWEL):
            position += 1
            phoneme = get_phoneme(position)
            if not _has_flag(phoneme, P_FLAG_CONSONANT):
                if phoneme == 18 or phoneme == 19:
                    position += 1
                    if _has_flag(get_phoneme(position), P_FLAG_CONSONANT):
                        set_length(loop_index, get_length(loop_index) - 1)
                continue
            if phoneme is None:
                flags = P_FLAG_CONSONANT | FLAG_UNVOICED_STOPCONS
            else:
                flags = PHONEME_FLAGS[phoneme]
            if not (flags & P_FLAG_VOICED):
                if flags & FLAG_UNVOICED_STOPCONS:
                    a = get_length(loop_index)
                    set_length(loop_index, a - (a >> 3))
                continue
            a = get_length(loop_index)
            set_length(loop_index, (a >> 2) + a + 1)
            continue

        if _has_flag(phoneme, FLAG_NASAL):
            position += 1
            phoneme = get_phoneme(position)
            if phoneme is not None and _has_flag(phoneme, FLAG_STOPCONS):
                set_length(position, 6)
                set_length(position - 1, 5)
            continue

        if _has_flag(phoneme, FLAG_STOPCONS):
            while True:
                position += 1
                phoneme = get_phoneme(position)
                if phoneme != 0:
                    break
            if phoneme is not None and _has_flag(phoneme, FLAG_STOPCONS):
                set_length(position, (get_length(position) >> 1) + 1)
                set_length(loop_index, (get_length(loop_index) >> 1) + 1)
            continue

        if (position > 0 and _has_flag(phoneme, FLAG_LIQUIC)
                and _has_flag(get_phoneme(position - 1), FLAG_STOPCONS)):
            set_length(position, get_length(position) - 2)


def _prolong(get_phoneme, insert_phoneme, get_stress):
    pos = -1
    while True:
        pos += 1
        index = get_phoneme(pos)
        if index is None:
            break
        if not _has_flag(index, FLAG_STOPCONS):
            continue
        if _has_flag(index, FLAG_UNVOICED_STOPCONS):
            x = pos
            while True:
                x += 1
                nxt = get_phoneme(x)
                if nxt != 0:
                    break
            if nxt is not None and (_has_flag(nxt, FLAG_0008) or nxt == 36 or nxt == 37):
                continue
        insert_phoneme(pos + 1, index + 1, get_stress(pos), _comb(index + 1) & 0xFF)
        insert_phoneme(pos + 2, index + 2, get_stress(pos), _comb(index + 2) & 0xFF)
        pos += 2
